<script setup lang="ts">
import { computed, ref } from 'vue';
import { t } from './lib';
import { demoCalls } from './demo-data';
import { trackAction } from './analytics';
const filter = ref('all'), selectedId = ref('demo-02');
const calls = computed(() => demoCalls.filter(c => filter.value === 'all' || (filter.value === 'slow' ? c.duration >= 5000 : c.status === 'error')));
const selected = computed(() => demoCalls.find(c => c.id === selectedId.value)!);
const tokens = demoCalls.reduce((sum, c) => sum + c.input + c.output, 0);
const cost = demoCalls.reduce((sum, c) => sum + (c.cost ?? 0), 0);
function chooseFilter(value: string) { filter.value = value; if (!calls.value.some(c => c.id === selectedId.value) && calls.value.length) selectedId.value = calls.value[0].id; }
</script>
<template>
  <main class="public-content demo-page">
    <div class="page-intro"><span class="eyebrow">{{ t('EXPLORE WITHOUT SIGNING UP', '无需登录，直接体验') }}</span><h1>{{ t('Find the request behind the cost', '从费用找到具体请求') }}</h1><p>{{ t('Select a request to see its steps. Filter slow or failed requests to explore how you would investigate a problem.', '点击一条请求查看调用步骤，筛选慢请求或失败请求，体验如何定位问题。') }}</p></div>
    <div class="notice demo-disclaimer"><strong>{{ t('Sample data', '示例数据') }}</strong> · {{ t('All requests, model names and costs below are fictional. This demo runs locally in your browser, never calls a model and does not change your account or quota.', '下方请求、模型名称和费用均为虚构示例。演示只在浏览器中运行，不调用模型，不修改你的账号或额度。') }}</div>
    <div class="demo-metrics"><article class="panel"><span>{{ t('Requests', '请求数') }}</span><strong>{{ demoCalls.length }}</strong></article><article class="panel"><span>{{ t('Reported tokens', '已上报 Token') }}</span><strong>{{ tokens.toLocaleString() }}</strong></article><article class="panel"><span>{{ t('Known estimated model cost', '已知模型估算成本') }}</span><strong>${{ cost.toFixed(4) }}</strong><small>{{ t('1 request has unknown cost', '1 条请求成本未知') }}</small></article><article class="panel"><span>{{ t('Slow requests (≥ 5 seconds)', '慢请求（≥ 5 秒）') }}</span><strong>{{ demoCalls.filter(c => c.duration >= 5000).length }}</strong></article></div>
    <div class="demo-layout"><section class="panel"><h2>{{ t('Explore requests', '查看请求') }}</h2><div class="demo-filters" aria-label="Request filter"><button v-for="item in [{id:'all', en:'All', zh:'全部'}, {id:'slow', en:'Slow requests', zh:'慢请求'}, {id:'error', en:'Failed requests', zh:'失败请求'}]" :key="item.id" class="btn" :class="{primary:filter===item.id}" :aria-pressed="filter===item.id" @click="chooseFilter(item.id)">{{ t(item.en,item.zh) }}</button></div>
      <div class="demo-calls"><button v-for="call in calls" :key="call.id" :aria-pressed="selectedId===call.id" :class="['demo-call', {selected:selectedId===call.id}]" @click="selectedId=call.id"><span><strong>{{ t(call.name,call.zh) }}</strong><small>{{ call.feature }} · {{ call.model }}</small></span><span>{{ (call.duration/1000).toFixed(2) }} s<small :class="call.status==='error' ? 'demo-error' : ''">{{ call.status==='error' ? t('Failed','失败') : t('Success','成功') }}</small></span><span>{{ call.cost===null ? t('Unknown','未知') : '$'+call.cost.toFixed(4) }}</span></button></div>
    </section><section class="panel demo-detail" aria-live="polite"><span class="badge">{{ t('Request details', '请求详情') }}</span><h2>{{ t(selected.name,selected.zh) }}</h2><dl><div><dt>{{ t('Model', '模型') }}</dt><dd>{{ selected.model }}</dd></div><div><dt>{{ t('Input / output tokens', '输入 / 输出 Token') }}</dt><dd>{{ selected.input.toLocaleString() }} / {{ selected.output.toLocaleString() }}</dd></div><div><dt>{{ t('Estimated model cost', '模型估算成本') }}</dt><dd>{{ selected.cost===null ? t('Unknown','未知') : '$'+selected.cost.toFixed(4) }}</dd></div></dl><h3>{{ t('Where the time went', '耗时分布') }}</h3><ol class="demo-steps"><li v-for="step in selected.steps" :key="step.name"><div><strong>{{ t(step.name,step.zh) }}</strong><span>{{ (step.duration/1000).toFixed(2) }} s</span></div><div class="demo-step-track"><span :style="{width:Math.max(2,step.duration/selected.duration*100)+'%'}"></span></div></li></ol><p>{{ selected.status==='error' ? t('The model step timed out. Its final usage and cost were not reported, so cost stays unknown instead of being counted as zero.', '模型步骤超时，未上报最终用量与成本，因此显示未知，不会按零费用处理。') : selected.duration>=5000 ? t('Most time is spent in the model step. In your application, inspect the request size and model choice before changing unrelated services.', '主要时间花在模型步骤。在实际应用中，可以先检查请求规模和模型选择。') : t('This request completed successfully. Use the same view to compare slower requests and their model usage.', '这条请求已成功完成。你可以用同样方式对比慢请求及其模型用量。') }}</p><small>{{ t('Illustrative estimates only. Model provider charges and MeterTrail monitoring units are separate.', '仅用于展示估算结果。模型供应商费用与 MeterTrail 监控额度分别计算。') }}</small></section></div>
    <section class="bottom-cta"><div><h2>{{ t('See your own application here', '在这里看到你自己的应用') }}</h2><p>{{ t('Send one trace from your backend to get started.', '从服务端发送一条调用记录，即可开始。') }}</p></div><RouterLink to="/tutorials" class="btn primary" @click="trackAction('open_tutorial','/demo')">{{ t('Choose an integration tutorial', '选择接入教程') }}</RouterLink><RouterLink to="/register" class="btn" @click="trackAction('start_free','/demo')">{{ t('Start free', '免费开始') }}</RouterLink></section>
  </main>
</template>
